-- Schema and data of a new, fully migrated panel database.
-- goose version 160
-- Generated by `go test ./internal/panel/store -run '^TestSchemaSnapshot$' -update`; do not edit by hand.
PRAGMA defer_foreign_keys = ON;
CREATE TABLE admin (
    id           TEXT PRIMARY KEY,
    display_name TEXT NOT NULL,
    role         TEXT NOT NULL CHECK (role IN ('owner', 'helper', 'readonly')),
    user_handle  BLOB NOT NULL UNIQUE,      -- WebAuthn user.id, random, never shown
    created_at   INTEGER NOT NULL
) STRICT;
CREATE TABLE admin_password (
    admin_id    TEXT PRIMARY KEY REFERENCES admin(id) ON DELETE CASCADE,
    login       TEXT NOT NULL UNIQUE,        -- lower case
    hash        TEXT NOT NULL,               -- argon2id, PHC string
    totp_secret BLOB NOT NULL,               -- sealed with the master key, AAD = admin id
    totp_step   INTEGER NOT NULL DEFAULT 0,  -- last accepted 30 s step: a code works once
    created_at  INTEGER NOT NULL
) STRICT;
CREATE TABLE api_token (
    id            TEXT PRIMARY KEY,                       -- tok_...
    name          TEXT NOT NULL,
    name_key      TEXT NOT NULL,                          -- lower(name): uniqueness among unrevoked tokens
    profile       TEXT NOT NULL CHECK (profile IN ('readonly', 'operator', 'admin')),
    secret_hash   BLOB NOT NULL UNIQUE,                   -- SHA-256 of the secret
    hint          TEXT NOT NULL,                          -- last 4 characters of the secret
    rate_per_min  INTEGER NOT NULL CHECK (rate_per_min BETWEEN 1 AND 600),
    created_by    TEXT NOT NULL,                          -- admin id (no FK: the row outlives the admin)
    created_at    INTEGER NOT NULL,
    expires_at    INTEGER NOT NULL,
    revoked_at    INTEGER NOT NULL DEFAULT 0,
    revoked_by    TEXT NOT NULL DEFAULT '',
    last_used_at  INTEGER NOT NULL DEFAULT 0,
    last_used_ip  TEXT NOT NULL DEFAULT '',
    last_used_via TEXT NOT NULL DEFAULT '' CHECK (last_used_via IN ('', 'api', 'mcp'))
, assistant_only INTEGER NOT NULL DEFAULT 0 CHECK (assistant_only IN (0, 1)), allow_bulk_user_changes INTEGER NOT NULL DEFAULT 0 CHECK (allow_bulk_user_changes IN (0, 1))) STRICT;
CREATE TABLE assistant_budget_reservation (
    id            TEXT PRIMARY KEY,
    month         TEXT NOT NULL,
    admin_id      TEXT NOT NULL,
    provider      INTEGER NOT NULL,
    model         TEXT NOT NULL,
    estimate_usd  REAL NOT NULL CHECK (estimate_usd >= 0),
    state         TEXT NOT NULL DEFAULT 'reserved' CHECK (state IN ('reserved', 'settled')),
    created_at    INTEGER NOT NULL,
    settled_at    INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE assistant_conversation (
    id          TEXT PRIMARY KEY,
    admin_id    TEXT NOT NULL,
    title_enc   BLOB NOT NULL DEFAULT X'',
    summary_enc BLOB NOT NULL DEFAULT X'',
    created_at  INTEGER NOT NULL,
    updated_at  INTEGER NOT NULL,
    segment     INTEGER NOT NULL DEFAULT 0
, task_id TEXT NOT NULL DEFAULT '', unread INTEGER NOT NULL DEFAULT 0 CHECK (unread IN (0, 1))) STRICT;
CREATE TABLE assistant_follow_up (
    id              TEXT    PRIMARY KEY,
    conversation_id TEXT    NOT NULL,
    admin_id        TEXT    NOT NULL,
    note_enc        BLOB    NOT NULL,
    plan_id         TEXT    NOT NULL DEFAULT '',
    delay_s         INTEGER NOT NULL DEFAULT 0,
    notify_telegram INTEGER NOT NULL DEFAULT 0 CHECK (notify_telegram IN (0, 1)),
    created_at      INTEGER NOT NULL,
    due_at          INTEGER NOT NULL DEFAULT 0,
    lease_id        TEXT    NOT NULL DEFAULT '',
    lease_until     INTEGER NOT NULL DEFAULT 0,
    attempts        INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE assistant_lock (
    conversation_id TEXT PRIMARY KEY,
    admin_id        TEXT NOT NULL,
    lease_id        TEXT NOT NULL,
    expires_at      INTEGER NOT NULL,
    stop_requested  INTEGER NOT NULL DEFAULT 0 CHECK (stop_requested IN (0, 1))
) STRICT;
CREATE TABLE assistant_memory (
    id              TEXT PRIMARY KEY,
    admin_id        TEXT NOT NULL,
    text_enc        BLOB NOT NULL,
    by_assistant    INTEGER NOT NULL DEFAULT 0 CHECK (by_assistant IN (0, 1)),
    conversation_id TEXT NOT NULL DEFAULT '',
    created_at      INTEGER NOT NULL,
    updated_at      INTEGER NOT NULL
) STRICT;
CREATE TABLE assistant_message (
    id              TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL,
    admin_id        TEXT NOT NULL,
    role            TEXT NOT NULL CHECK (role IN ('user', 'assistant', 'summary')),
    segment         INTEGER NOT NULL DEFAULT 0,
    body_enc        BLOB NOT NULL,
    created_at      INTEGER NOT NULL
) STRICT;
CREATE TABLE assistant_plan (
    id              TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL,
    admin_id        TEXT NOT NULL,
    token_id        TEXT NOT NULL REFERENCES api_token(id),
    tool            TEXT NOT NULL,
    confirm_enc     BLOB NOT NULL,
    card_enc        BLOB NOT NULL,
    inbox_only      INTEGER NOT NULL DEFAULT 0 CHECK (inbox_only IN (0, 1)),
    state           TEXT NOT NULL DEFAULT 'proposed',
    created_at      INTEGER NOT NULL,
    expires_at      INTEGER NOT NULL,
    updated_at      INTEGER NOT NULL
) STRICT;
CREATE TABLE assistant_provider (
    provider         INTEGER PRIMARY KEY,
    key_enc          BLOB NOT NULL DEFAULT X'',
    key_hint         TEXT NOT NULL DEFAULT '',
    added_at         INTEGER NOT NULL DEFAULT 0,
    model            TEXT NOT NULL DEFAULT '',
    budget_usd       REAL NOT NULL DEFAULT 20 CHECK (budget_usd >= 0),
    last_error_code  TEXT NOT NULL DEFAULT '',
    last_error_at    INTEGER NOT NULL DEFAULT 0
, custom_name TEXT NOT NULL DEFAULT '', custom_url TEXT NOT NULL DEFAULT '', allow_local INTEGER NOT NULL DEFAULT 0 CHECK (allow_local IN (0, 1)), input_usd_per_mtok REAL NOT NULL DEFAULT 0 CHECK (input_usd_per_mtok >= 0), output_usd_per_mtok REAL NOT NULL DEFAULT 0 CHECK (output_usd_per_mtok >= 0)) STRICT;
CREATE TABLE assistant_rate (
    admin_id     TEXT NOT NULL,
    minute       INTEGER NOT NULL,
    turns        INTEGER NOT NULL,
    PRIMARY KEY(admin_id, minute)
) STRICT;
CREATE TABLE assistant_settings (
    id             INTEGER PRIMARY KEY CHECK (id = 1),
    enabled        INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
    provider       INTEGER NOT NULL DEFAULT 0,
    effort         INTEGER NOT NULL DEFAULT 2,
    audience       INTEGER NOT NULL DEFAULT 1,
    panel_notes    TEXT NOT NULL DEFAULT '',
    retention_days INTEGER NOT NULL DEFAULT 90,
    updated_at     INTEGER NOT NULL DEFAULT 0
, panel_notes_enc BLOB NOT NULL DEFAULT X'', fallback_provider INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE assistant_usage (
    month          TEXT NOT NULL,
    admin_id       TEXT NOT NULL,
    provider       INTEGER NOT NULL,
    input_tokens   INTEGER NOT NULL DEFAULT 0,
    output_tokens  INTEGER NOT NULL DEFAULT 0,
    usd            REAL NOT NULL DEFAULT 0,
    turns          INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY(month, admin_id, provider)
) STRICT;
CREATE TABLE "audit" (
    id     INTEGER PRIMARY KEY AUTOINCREMENT,
    ts     INTEGER NOT NULL,
    actor  TEXT NOT NULL,
    action TEXT NOT NULL,
    params TEXT NOT NULL DEFAULT '{}',
    result TEXT NOT NULL,
    source TEXT NOT NULL DEFAULT 'panel' CHECK (source IN ('panel', 'bot', 'mcp', 'api', 'assistant')),
    ip     TEXT NOT NULL DEFAULT ''
) STRICT;
CREATE TABLE auth_ceremony (
    id TEXT PRIMARY KEY,
    kind TEXT NOT NULL,
    source_key TEXT NOT NULL DEFAULT '',
    session_data TEXT NOT NULL CHECK (json_valid(session_data)),
    token_hash BLOB NOT NULL DEFAULT X'',
    admin_id TEXT NOT NULL DEFAULT '',
    admin_user_handle BLOB NOT NULL DEFAULT X'',
    name TEXT NOT NULL DEFAULT '',
    login TEXT NOT NULL DEFAULT '',
    password_hash TEXT NOT NULL DEFAULT '',
    totp_enc BLOB NOT NULL DEFAULT X'',
    tries INTEGER NOT NULL DEFAULT 0,
    expires_at INTEGER NOT NULL
) STRICT;
CREATE TABLE awg_peer (
    credential_id TEXT PRIMARY KEY REFERENCES device_credential (id) ON DELETE CASCADE,
    profile_id    TEXT    NOT NULL REFERENCES profile (id) ON DELETE CASCADE,
    idx           INTEGER NOT NULL CHECK (idx >= 2),
    public_key    TEXT    NOT NULL,
    released_at   INTEGER NOT NULL DEFAULT 0,      -- 0 = live; > 0 = start of the quarantine
    created_at    INTEGER NOT NULL
) STRICT;
CREATE TABLE awg_retained_key (
    profile_id  TEXT    NOT NULL REFERENCES profile (id) ON DELETE CASCADE,
    node_id     TEXT    NOT NULL REFERENCES node (id)    ON DELETE CASCADE,
    state_enc   BLOB    NOT NULL,
    public_json TEXT    NOT NULL CHECK (json_valid(public_json)),
    created_at  INTEGER NOT NULL,
    PRIMARY KEY (profile_id, node_id)
) STRICT;
CREATE TABLE batch_guard (
    failed INTEGER NOT NULL,
    CONSTRAINT batch_guard CHECK (failed = 0)
);
CREATE TABLE client_debug (
    id           TEXT    PRIMARY KEY,
    user_id      TEXT    NOT NULL,
    device_id    TEXT    NOT NULL,
    actor        TEXT    NOT NULL DEFAULT '',
    unasked      INTEGER NOT NULL DEFAULT 0 CHECK (unasked IN (0, 1)),
    note         TEXT    NOT NULL DEFAULT '',
    level        TEXT    NOT NULL DEFAULT 'info' CHECK (level IN ('info', 'debug')),
    requested_at INTEGER NOT NULL,
    expires_at   INTEGER NOT NULL,
    state        TEXT    NOT NULL CHECK (state IN ('open', 'received', 'declined', 'cancelled', 'expired')),
    closed_at    INTEGER NOT NULL DEFAULT 0,
    records      INTEGER NOT NULL DEFAULT 0,
    bytes        INTEGER NOT NULL DEFAULT 0,
    dropped_kv   INTEGER NOT NULL DEFAULT 0,
    first_ms     INTEGER NOT NULL DEFAULT 0,
    last_ms      INTEGER NOT NULL DEFAULT 0,
    app          TEXT    NOT NULL DEFAULT '',
    read_at      INTEGER NOT NULL DEFAULT 0,
    read_by      TEXT    NOT NULL DEFAULT ''
) STRICT;
CREATE TABLE client_probe_report (
    report         TEXT    NOT NULL,
    at             INTEGER NOT NULL,
    node_id        TEXT    NOT NULL,
    kind           TEXT    NOT NULL,
    port           INTEGER NOT NULL,
    verdict        TEXT    NOT NULL,
    detail_json    TEXT    NOT NULL DEFAULT '{}',
    vpn            INTEGER NOT NULL DEFAULT 0 CHECK (vpn IN (0, 1)),
    direct_checked INTEGER NOT NULL DEFAULT 0 CHECK (direct_checked IN (0, 1)),
    asn            INTEGER NOT NULL DEFAULT 0,
    operator       TEXT    NOT NULL DEFAULT '',
    country        TEXT    NOT NULL DEFAULT '',
    region         TEXT    NOT NULL DEFAULT '',
    net_type       TEXT    NOT NULL DEFAULT '',
    PRIMARY KEY (report, node_id, kind, port)
) STRICT;
CREATE TABLE country_blocklist_check (
    node_id      TEXT    NOT NULL,
    at           INTEGER NOT NULL,
    in_rkn       INTEGER NOT NULL DEFAULT 0 CHECK (in_rkn IN (0, 1)),
    rkn_subnet   TEXT    NOT NULL DEFAULT '',
    listed_by    TEXT    NOT NULL DEFAULT '',
    cdn_provider TEXT    NOT NULL DEFAULT '',
    cdn_region   TEXT    NOT NULL DEFAULT '',
    lists_at     INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (node_id, at)
) STRICT;
CREATE TABLE "country_check" (
    node_id     TEXT    NOT NULL,
    country     TEXT    NOT NULL,
    family      INTEGER NOT NULL DEFAULT 4 CHECK (family IN (4, 6)),
    at          INTEGER NOT NULL,
    verdict     TEXT    NOT NULL,
    detail_json TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(detail_json)),
    PRIMARY KEY (node_id, country, family, at)
) STRICT;
CREATE TABLE country_ext_check (
    node_id     TEXT    NOT NULL,
    source      TEXT    NOT NULL,
    at          INTEGER NOT NULL,
    verdict     TEXT    NOT NULL,
    detail_json TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(detail_json)),
    PRIMARY KEY (node_id, source, at)
) STRICT;
CREATE TABLE country_tspu_check (
    node_id     TEXT    NOT NULL,
    vantage     TEXT    NOT NULL,
    at          INTEGER NOT NULL,
    verdict     TEXT    NOT NULL,
    dpi_hop     INTEGER NOT NULL DEFAULT 0,
    control_ok  INTEGER NOT NULL DEFAULT 0 CHECK (control_ok IN (0, 1)),
    detail_json TEXT    NOT NULL DEFAULT '[]',
    PRIMARY KEY (node_id, vantage, at)
) STRICT;
CREATE TABLE debug_capture (
    id         TEXT    PRIMARY KEY,
    node_id    TEXT    NOT NULL,
    actor      TEXT    NOT NULL,
    level      TEXT    NOT NULL CHECK (level IN ('debug', 'info')),
    sources    TEXT    NOT NULL DEFAULT '',
    duration_s INTEGER NOT NULL,
    started_at INTEGER NOT NULL,
    ends_at    INTEGER NOT NULL,
    state      TEXT    NOT NULL CHECK (state IN ('running', 'done')),
    end_reason TEXT    NOT NULL DEFAULT '',
    records    INTEGER NOT NULL DEFAULT 0,
    bytes      INTEGER NOT NULL DEFAULT 0,
    dropped    INTEGER NOT NULL DEFAULT 0
, last_chunk_seq INTEGER NOT NULL DEFAULT -1) STRICT;
CREATE TABLE debug_capture_line (
    capture_id TEXT    NOT NULL,
    seq        INTEGER NOT NULL,
    at_ms      INTEGER NOT NULL,
    level      INTEGER NOT NULL CHECK (level BETWEEN 0 AND 3),
    source     TEXT    NOT NULL,
    message    TEXT    NOT NULL,
    attrs_json TEXT    NOT NULL DEFAULT '{}',
    PRIMARY KEY (capture_id, seq)
) STRICT;
CREATE TABLE decoy_site (
    id           TEXT PRIMARY KEY,
    name         TEXT NOT NULL COLLATE NOCASE CHECK (length(name) BETWEEN 1 AND 60),
    note         TEXT NOT NULL DEFAULT '' CHECK (length(note) <= 200),
    source       TEXT NOT NULL CHECK (source IN ('upload', 'assistant', 'mcp')),
    source_label TEXT NOT NULL DEFAULT '',
    state        TEXT NOT NULL CHECK (state IN ('draft', 'ready')),
    bundle_hash  TEXT NOT NULL,
    created_at   INTEGER NOT NULL,
    created_by   TEXT NOT NULL DEFAULT '',
    updated_at   INTEGER NOT NULL,
    updated_by   TEXT NOT NULL DEFAULT ''
);
CREATE TABLE decoy_site_version (
    site_id     TEXT NOT NULL,
    seq         INTEGER NOT NULL,
    bundle_hash TEXT NOT NULL,
    created_at  INTEGER NOT NULL,
    created_by  TEXT NOT NULL DEFAULT '',
    size_bytes  INTEGER NOT NULL DEFAULT 0,
    file_count  INTEGER NOT NULL DEFAULT 0,
    files_json  TEXT NOT NULL DEFAULT '',
    title       TEXT NOT NULL DEFAULT '',
    checks_json TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (site_id, seq)
);
CREATE TABLE device (
    id                  TEXT PRIMARY KEY,                       -- dev_...
    user_id             TEXT    NOT NULL REFERENCES user (id) ON DELETE CASCADE,
    -- sha256 of the client HWID header (Happ etc.). NULL = the implicit per-user device used
    -- for subscription fetches without a HWID (one shared token, counted as 1 device).
    hwid_hash           BLOB,
    platform            TEXT    NOT NULL DEFAULT '',
    model               TEXT    NOT NULL DEFAULT '',
    os_version          TEXT    NOT NULL DEFAULT '',
    first_seen_at       INTEGER NOT NULL,
    last_seen_at        INTEGER NOT NULL,
    created_at          INTEGER NOT NULL,
    revoked_at          INTEGER                                 -- soft delete: stats of a revoked device must still resolve
, kind TEXT NOT NULL DEFAULT 'link' CHECK (kind IN ('link', 'key')), client TEXT NOT NULL DEFAULT '', blocked_at INTEGER, used_bytes INTEGER NOT NULL DEFAULT 0, key_hash BLOB CHECK (key_hash IS NULL OR length(key_hash) = 32), enrol_token_hash BLOB CHECK (enrol_token_hash IS NULL OR length(enrol_token_hash) = 32), last_connected_at INTEGER NOT NULL DEFAULT 0, awg_route TEXT NOT NULL DEFAULT '' CHECK (awg_route IN ('', 'ru-direct'))) STRICT;
CREATE TABLE device_credential (
    id                  TEXT PRIMARY KEY,                       -- crd_...  (= Credential.cred_id on the wire)
    device_id           TEXT    NOT NULL REFERENCES device (id) ON DELETE CASCADE,
    user_id             TEXT    NOT NULL REFERENCES user (id)   ON DELETE CASCADE,  -- denormalized for the access query
    protocol            TEXT    NOT NULL,
    secret_enc          BLOB    NOT NULL,                       -- vault, AAD = id; what the client presents (hy2 token)
    data_json           TEXT    NOT NULL CHECK (json_valid(data_json)),  -- verifier sent to nodes (hy2: {"auth_sha256":...})
    created_at          INTEGER NOT NULL,
    revoked_at          INTEGER                                 -- soft delete
, profile_id TEXT REFERENCES profile (id) ON DELETE CASCADE, config_epoch INTEGER NOT NULL DEFAULT 0, dns_sig TEXT NOT NULL DEFAULT '' CHECK (dns_sig = '' OR json_valid(dns_sig)), path TEXT NOT NULL DEFAULT '' CHECK (path = '' OR path = 'ipv6' OR path GLOB 'relay:*')) STRICT;
CREATE TABLE dns_preset (
    id          TEXT PRIMARY KEY,                       -- dns_<random>, or dns_builtin_<slug> for the built-ins
    name        TEXT    NOT NULL COLLATE NOCASE UNIQUE,
    description TEXT    NOT NULL DEFAULT '',
    builtin     INTEGER NOT NULL DEFAULT 0 CHECK (builtin IN (0, 1)),
    servers     TEXT    NOT NULL,
    split       TEXT    NOT NULL DEFAULT '[]',
    ipv4_only   INTEGER NOT NULL DEFAULT 0 CHECK (ipv4_only IN (0, 1)),
    created_at  INTEGER NOT NULL,
    updated_at  INTEGER NOT NULL
, split_direct INTEGER NOT NULL DEFAULT 0 CHECK (split_direct IN (0, 1)), sort INTEGER NOT NULL DEFAULT 0, preferred_transport TEXT NOT NULL DEFAULT 'plain' CHECK (preferred_transport IN ('plain', 'dot', 'doh')), block_ads INTEGER NOT NULL DEFAULT 0 CHECK (block_ads IN (0, 1)), block_max INTEGER NOT NULL DEFAULT 0 CHECK (block_max IN (0, 1)), torrent_direct INTEGER NOT NULL DEFAULT 0 CHECK (torrent_direct IN (0, 1))) STRICT;
CREATE TABLE doctor_accept (
    node_id             TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    check_id            TEXT    NOT NULL,
    detail_code         TEXT    NOT NULL DEFAULT '',             -- the DoctorResult.detail_code that was accepted
    accepted_by         TEXT    NOT NULL,                        -- admin id
    accepted_at         INTEGER NOT NULL,
    PRIMARY KEY (node_id, check_id)
) STRICT, WITHOUT ROWID;
CREATE TABLE doctor_result (
    node_id             TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    check_id            TEXT    NOT NULL,
    status              INTEGER NOT NULL CHECK (status BETWEEN 1 AND 4),  -- agent.proto DoctorStatus
    title_key           TEXT    NOT NULL DEFAULT '',
    detail              TEXT    NOT NULL DEFAULT '',
    params_json         TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(params_json)),
    fix_id              TEXT    NOT NULL DEFAULT '',
    measured_unix       INTEGER NOT NULL DEFAULT 0,
    received_unix       INTEGER NOT NULL, detail_code TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (node_id, check_id)
) STRICT, WITHOUT ROWID;
CREATE TABLE enrollment_token (
    id                  TEXT PRIMARY KEY,                       -- enr_...
    node_id             TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    token_hash          BLOB    NOT NULL UNIQUE,                -- sha256(token); lookup key on Enroll
    created_by          TEXT    NOT NULL,                       -- admin id, no FK (see header)
    created_at          INTEGER NOT NULL,
    expires_at          INTEGER NOT NULL,
    used_at             INTEGER,                                -- NULL = unused
    csr_key_hash        BLOB,                                   -- sha256 of the CSR public key of the first use (idempotent retry window)
    issued_serial       TEXT                                    -- node_cert.serial handed out
) STRICT;
CREATE TABLE event (
    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    ts                  INTEGER NOT NULL,
    severity            INTEGER NOT NULL CHECK (severity BETWEEN 1 AND 3),  -- 1 info, 2 warning, 3 error
    code                TEXT    NOT NULL,
    source              TEXT    NOT NULL CHECK (source IN ('agent', 'panel', 'admin')),
    node_id             TEXT,
    user_id             TEXT,
    device_id           TEXT,
    inbound_id          TEXT,
    params_json         TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(params_json)),
    -- agent events: belt-and-braces dedup on top of node.last_seq
    src_instance        TEXT,
    src_seq             INTEGER
, received_at INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE goose_db_version (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		version_id INTEGER NOT NULL,
		is_applied INTEGER NOT NULL,
		tstamp TIMESTAMP DEFAULT (datetime('now'))
	);
CREATE TABLE health_alert (
    id                  TEXT PRIMARY KEY,                       -- alt_...
    kind                TEXT    NOT NULL,                       -- node_down | host_blip | no_traffic | check_failed | doctor_warn | ...
    severity            INTEGER NOT NULL CHECK (severity BETWEEN 1 AND 3),  -- 1 info, 2 warning, 3 critical
    node_id             TEXT    NOT NULL DEFAULT '',
    subject             TEXT    NOT NULL DEFAULT '',
    params_json         TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(params_json)),
    title_key           TEXT    NOT NULL,
    why_key             TEXT    NOT NULL DEFAULT '',
    first_seen          INTEGER NOT NULL,
    last_seen           INTEGER NOT NULL,
    resolved_at         INTEGER NOT NULL DEFAULT 0,             -- 0 = active
    resolution          TEXT    NOT NULL DEFAULT '',            -- cleared | fix_applied | node_retired | node_returned | superseded
    muted_until         INTEGER NOT NULL DEFAULT 0,
    created_at          INTEGER NOT NULL
, opened_at INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE health_check_daily (
    inbound_id          TEXT    NOT NULL REFERENCES inbound (id) ON DELETE CASCADE,
    day                 INTEGER NOT NULL CHECK (day % 86400 = 0),
    ok                  INTEGER NOT NULL DEFAULT 0,
    failed              INTEGER NOT NULL DEFAULT 0,
    degraded            INTEGER NOT NULL DEFAULT 0,
    p50_ms              INTEGER NOT NULL DEFAULT 0,
    p95_ms              INTEGER NOT NULL DEFAULT 0, connect_p50_ms INTEGER NOT NULL DEFAULT 0, connect_p95_ms INTEGER NOT NULL DEFAULT 0, response_p50_ms INTEGER NOT NULL DEFAULT 0, response_p95_ms INTEGER NOT NULL DEFAULT 0, jitter_ms INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (inbound_id, day)
) STRICT, WITHOUT ROWID;
CREATE TABLE health_check_sample (
    inbound_id          TEXT    NOT NULL REFERENCES inbound (id) ON DELETE CASCADE,
    at                  INTEGER NOT NULL,
    status              INTEGER NOT NULL CHECK (status BETWEEN 1 AND 3),
    latency_ms          INTEGER NOT NULL DEFAULT 0,
    exit_ip             TEXT    NOT NULL DEFAULT '',
    exit_country        TEXT    NOT NULL DEFAULT '',
    error_code          TEXT    NOT NULL DEFAULT '',
    error_detail        TEXT    NOT NULL DEFAULT '', connect_ms INTEGER NOT NULL DEFAULT 0, response_ms INTEGER NOT NULL DEFAULT 0, udp_sent INTEGER NOT NULL DEFAULT 0, udp_lost INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (inbound_id, at)
) STRICT, WITHOUT ROWID;
CREATE TABLE health_probe_cred (
    inbound_id          TEXT PRIMARY KEY REFERENCES inbound (id) ON DELETE CASCADE,
    cred_id             TEXT    NOT NULL UNIQUE,                -- crd_... = Credential.cred_id on the wire
    secret_enc          BLOB    NOT NULL,                       -- vault, AAD = cred_id; what the probe client presents
    data_json           TEXT    NOT NULL CHECK (json_valid(data_json)),  -- verifier shipped to the node (hy2: {"auth_sha256":...})
    created_at          INTEGER NOT NULL
, awg_idx INTEGER NOT NULL DEFAULT 0 CHECK (awg_idx = 0 OR awg_idx >= 2)) STRICT;
CREATE TABLE inbound (
    id                  TEXT PRIMARY KEY,                       -- inb_...
    profile_id          TEXT    NOT NULL REFERENCES profile (id) ON DELETE RESTRICT,
    node_id             TEXT    NOT NULL REFERENCES node (id)    ON DELETE RESTRICT,
    port_override       INTEGER CHECK (port_override BETWEEN 1 AND 65535),
    tls_server_name_override TEXT NOT NULL DEFAULT '',
    enabled             INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    spec_version        INTEGER NOT NULL DEFAULT 1,             -- goes into InboundSpec.spec_version; bumped with profile.version and overrides
    state               TEXT    NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'active', 'failed', 'disabled')),
    last_error          TEXT    NOT NULL DEFAULT '',
    applied_spec_hash   TEXT    NOT NULL DEFAULT '',            -- InboundResult.spec_hash
    cert_pin_sha256     TEXT    NOT NULL DEFAULT '',            -- InboundResult, for pinSHA256 in subscriptions
    cert_not_after      INTEGER NOT NULL DEFAULT 0,
    created_at          INTEGER NOT NULL,
    updated_at          INTEGER NOT NULL, plugin_state_enc   BLOB, plugin_public_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(plugin_public_json)), awg_health_json    TEXT NOT NULL DEFAULT '' CHECK (awg_health_json = '' OR json_valid(awg_health_json)), awg_health_at      INTEGER NOT NULL DEFAULT 0, direct_in_subscriptions INTEGER NOT NULL DEFAULT 1 CHECK (direct_in_subscriptions IN (0, 1)), reality_target_override TEXT NOT NULL DEFAULT '', public_port INTEGER NOT NULL DEFAULT 0 CHECK (public_port BETWEEN 0 AND 65535),
    UNIQUE (profile_id, node_id)
) STRICT;
CREATE TABLE job_lease (
    name       TEXT PRIMARY KEY,
    holder     TEXT NOT NULL,
    expires_at INTEGER NOT NULL
) STRICT;
CREATE TABLE link_dns_option (
    preset_id  TEXT    NOT NULL PRIMARY KEY REFERENCES dns_preset (id) ON DELETE CASCADE,
    position   INTEGER NOT NULL,
    is_default INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1))
) STRICT;
CREATE TABLE link_hour (
    node_id      TEXT    NOT NULL,
    hour_start   INTEGER NOT NULL,
    inbound_id   TEXT    NOT NULL,
    cred_id      TEXT    NOT NULL,
    user_id      TEXT    NOT NULL DEFAULT '',
    connects     INTEGER NOT NULL DEFAULT 0,
    rejects      INTEGER NOT NULL DEFAULT 0,
    drops        INTEGER NOT NULL DEFAULT 0,
    stalls       INTEGER NOT NULL DEFAULT 0,
    online_s     INTEGER NOT NULL DEFAULT 0,
    unknown_keys INTEGER NOT NULL DEFAULT 0,
    hellos       INTEGER NOT NULL DEFAULT 0,
    handshakes   INTEGER NOT NULL DEFAULT 0, probe_handshakes INTEGER NOT NULL DEFAULT 0, client_closes INTEGER NOT NULL DEFAULT 0, freezes INTEGER NOT NULL DEFAULT 0, quiet INTEGER NOT NULL DEFAULT 0, accepted INTEGER NOT NULL DEFAULT 0, hellos_foreign INTEGER NOT NULL DEFAULT 0, rtt_ms_sum INTEGER NOT NULL DEFAULT 0, rtt_samples INTEGER NOT NULL DEFAULT 0, pkts_sent INTEGER NOT NULL DEFAULT 0, pkts_lost INTEGER NOT NULL DEFAULT 0, probe_pkts_sent INTEGER NOT NULL DEFAULT 0, probe_pkts_lost INTEGER NOT NULL DEFAULT 0, hs_unfinished INTEGER NOT NULL DEFAULT 0, tls_alerts_sent INTEGER NOT NULL DEFAULT 0, tls_alerts_recv INTEGER NOT NULL DEFAULT 0, tls_cert_refused INTEGER NOT NULL DEFAULT 0, reality_fallback INTEGER NOT NULL DEFAULT 0, auth_failed INTEGER NOT NULL DEFAULT 0, tcp_stalls INTEGER NOT NULL DEFAULT 0, tcp_stalls_16k INTEGER NOT NULL DEFAULT 0, initiations INTEGER NOT NULL DEFAULT 0, responses INTEGER NOT NULL DEFAULT 0, responses_unmatched INTEGER NOT NULL DEFAULT 0, hello_pq INTEGER NOT NULL DEFAULT 0, hello_classic INTEGER NOT NULL DEFAULT 0, hello_unknown INTEGER NOT NULL DEFAULT 0, tunnel_blocked INTEGER NOT NULL DEFAULT 0, tunnel_no_ipv4 INTEGER NOT NULL DEFAULT 0, tunnel_conn_refused INTEGER NOT NULL DEFAULT 0, tunnel_conn_unreachable INTEGER NOT NULL DEFAULT 0, tunnel_conn_dns INTEGER NOT NULL DEFAULT 0, tunnel_conn_other INTEGER NOT NULL DEFAULT 0, tunnel_timeout INTEGER NOT NULL DEFAULT 0, tunnel_other_deadlines INTEGER NOT NULL DEFAULT 0, tunnel_other_authority INTEGER NOT NULL DEFAULT 0, tunnel_other_icmp INTEGER NOT NULL DEFAULT 0, tunnel_other_dial INTEGER NOT NULL DEFAULT 0, tunnel_stream_closed INTEGER NOT NULL DEFAULT 0, tunnel_stream_cred_gone INTEGER NOT NULL DEFAULT 0, tunnel_stream_conn_limit INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (node_id, hour_start, inbound_id, cred_id)
) STRICT;
CREATE TABLE login_failure (
    login        TEXT PRIMARY KEY,
    failures     INTEGER NOT NULL,
    locked_until INTEGER NOT NULL DEFAULT 0,
    last_at      INTEGER NOT NULL
) STRICT;
CREATE TABLE mcp_plan (
    id             TEXT PRIMARY KEY,                      -- pln_...
    token_id       TEXT NOT NULL REFERENCES api_token(id) ON DELETE CASCADE,
    tool           TEXT NOT NULL,                         -- "rollout_start" (no _plan suffix)
    params_json    TEXT NOT NULL,                         -- canonical JSON of the validated arguments, no secrets
    params_hash    BLOB NOT NULL,                         -- SHA-256 of params_json
    confirm_hash   BLOB NOT NULL UNIQUE,                  -- SHA-256 of the confirm token
    facts_json     TEXT NOT NULL,                         -- [{"key","value","untrusted"}]
    summary        TEXT NOT NULL,                         -- the English paragraph the agent got
    danger         TEXT NOT NULL DEFAULT '[]',            -- JSON array: step_up | fleet | bulk
    needs_approval INTEGER NOT NULL CHECK (needs_approval IN (0, 1)),
    reason         TEXT NOT NULL DEFAULT '',              -- the agent's own words, untrusted, <= 300 chars
    inner_ref      TEXT NOT NULL DEFAULT '',              -- node_fix: the ApplyFix plan_id (never shown to the agent)
    status         TEXT NOT NULL CHECK (status IN
                     ('planned', 'awaiting', 'approved', 'rejected', 'expired', 'applying', 'applied', 'failed', 'cancelled')),
    created_at     INTEGER NOT NULL,
    expires_at     INTEGER NOT NULL,                      -- created_at + 600
    decided_by     TEXT NOT NULL DEFAULT '',              -- admin id of the approver or rejecter
    decided_at     INTEGER NOT NULL DEFAULT 0,
    applied_at     INTEGER NOT NULL DEFAULT 0,            -- while 'applying': when the apply began; after: when it finished
    result         TEXT NOT NULL DEFAULT '',
    error          TEXT NOT NULL DEFAULT ''
, outcome_code TEXT NOT NULL DEFAULT '', outcome_params TEXT NOT NULL DEFAULT '{}', owner_secret BLOB) STRICT;
CREATE TABLE network_hour (
    node_id    TEXT    NOT NULL,
    hour_start INTEGER NOT NULL,
    inbound_id TEXT    NOT NULL,
    asn        INTEGER NOT NULL,
    attempts   INTEGER NOT NULL,
    unfinished INTEGER NOT NULL,
    connects   INTEGER NOT NULL,
    broken     INTEGER NOT NULL,
    people     INTEGER NOT NULL,
    PRIMARY KEY (node_id, hour_start, inbound_id, asn)
) STRICT;
CREATE TABLE "node" (
    id                  TEXT PRIMARY KEY,
    name                TEXT    NOT NULL COLLATE NOCASE,
    address             TEXT    NOT NULL,
    country_code        TEXT    NOT NULL DEFAULT '',
    location            TEXT    NOT NULL DEFAULT '',
    provider            TEXT    NOT NULL DEFAULT '',
    notes               TEXT    NOT NULL DEFAULT '',
    dns_resolvers       TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(dns_resolvers)),
    liveness_timeout_s  INTEGER NOT NULL DEFAULT 90  CHECK (liveness_timeout_s BETWEEN 15 AND 3600),
    apply_timeout_s     INTEGER NOT NULL DEFAULT 120 CHECK (apply_timeout_s BETWEEN 10 AND 3600),
    dial_timeout_s      INTEGER NOT NULL DEFAULT 15  CHECK (dial_timeout_s BETWEEN 5 AND 120),
    state               TEXT    NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'active', 'retired')),
    cert_serial         TEXT,
    agent_version       TEXT    NOT NULL DEFAULT '',
    api_version         INTEGER NOT NULL DEFAULT 0,
    boot_at             INTEGER NOT NULL DEFAULT 0,
    last_seen_at        INTEGER NOT NULL DEFAULT 0,
    last_connected_at   INTEGER NOT NULL DEFAULT 0,
    last_disconnected_at INTEGER NOT NULL DEFAULT 0,
    agent_instance_id   TEXT    NOT NULL DEFAULT '',
    last_seq            INTEGER NOT NULL DEFAULT 0,
    desired_revision    INTEGER NOT NULL DEFAULT 0,
    desired_hash        TEXT    NOT NULL DEFAULT '',
    applied_revision    INTEGER NOT NULL DEFAULT 0,
    applied_hash        TEXT    NOT NULL DEFAULT '',
    created_at          INTEGER NOT NULL,
    retired_at          INTEGER,
    agent_built         INTEGER NOT NULL DEFAULT 0,
    agent_caps          TEXT    NOT NULL DEFAULT '',
    last_update_json    TEXT    NOT NULL DEFAULT '' CHECK (last_update_json = '' OR json_valid(last_update_json)),
    awg_backend         TEXT    NOT NULL DEFAULT 'auto' CHECK (awg_backend IN ('auto', 'kernel', 'userspace')),
    awg_prepare_json    TEXT    NOT NULL DEFAULT '' CHECK (awg_prepare_json = '' OR json_valid(awg_prepare_json))
, torrent_blocker_enabled INTEGER NOT NULL DEFAULT 0
    CHECK (torrent_blocker_enabled IN (0, 1)), bandwidth_mbps INTEGER NOT NULL DEFAULT 0
    CHECK (bandwidth_mbps BETWEEN 0 AND 1000000), client_ipv6 INTEGER NOT NULL DEFAULT 1
    CHECK (client_ipv6 IN (0, 1)), decoy_mode TEXT NOT NULL DEFAULT 'builtin'
    CHECK (decoy_mode IN ('builtin', 'panel', 'own')), decoy_bundle_hash TEXT NOT NULL DEFAULT '', decoy_agent_mode TEXT NOT NULL DEFAULT '', decoy_agent_hash TEXT NOT NULL DEFAULT '', ipv6_entry TEXT NOT NULL DEFAULT '', ipv6_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(ipv6_json)), udp_filtered_at INTEGER NOT NULL DEFAULT 0, udp_filtered_sender TEXT NOT NULL DEFAULT '', udp_filtered_checked_at INTEGER NOT NULL DEFAULT 0, networks_db_sha256 TEXT NOT NULL DEFAULT '', public_label TEXT NOT NULL DEFAULT ''
    CHECK (length(public_label) <= 40), link_sealed INTEGER NOT NULL DEFAULT 0 CHECK (link_sealed IN (0, 1)), bridge_port INTEGER NOT NULL DEFAULT 0 CHECK (bridge_port BETWEEN 0 AND 65535), bridge_path TEXT NOT NULL DEFAULT '', decoy_site_id TEXT NOT NULL DEFAULT '', hold_new_groups INTEGER NOT NULL DEFAULT 0 CHECK (hold_new_groups IN (0, 1)), share_changed_at INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE node_apply_meta (
    node_id     TEXT    PRIMARY KEY REFERENCES node (id) ON DELETE CASCADE,
    applied_at  INTEGER NOT NULL DEFAULT 0,   -- the last ApplyResult (or in-sync Hello) of the node
    status      TEXT    NOT NULL DEFAULT '',  -- applied | partial | in_sync (a Hello that matched, nothing was sent)
    duration_ms INTEGER NOT NULL DEFAULT 0,
    drift_since INTEGER NOT NULL DEFAULT 0    -- 0 = no drift; else when the node first applied a state other than the sent one
) STRICT;
CREATE TABLE node_cert (
    serial              TEXT PRIMARY KEY,                       -- hex
    node_id             TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    ca_id               TEXT    NOT NULL REFERENCES panel_ca (id),
    pem                 TEXT    NOT NULL,                       -- public material only
    not_before          INTEGER NOT NULL,
    not_after           INTEGER NOT NULL,
    issued_at           INTEGER NOT NULL,
    revoked_at          INTEGER,
    revoke_reason       TEXT    NOT NULL DEFAULT ''
) STRICT;
CREATE TABLE node_channel_measure (
    node_id      TEXT PRIMARY KEY REFERENCES node(id) ON DELETE CASCADE,
    started_unix INTEGER NOT NULL,
    at_unix      INTEGER NOT NULL DEFAULT 0,
    result_json  TEXT    NOT NULL DEFAULT ''
);
CREATE TABLE node_decoy_bundle (
    sha256  TEXT PRIMARY KEY,
    content BLOB NOT NULL CHECK (length(content) <= 2621440)
);
CREATE TABLE node_dns_option (
    node_id    TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    preset_id  TEXT    NOT NULL REFERENCES dns_preset (id) ON DELETE CASCADE,
    position   INTEGER NOT NULL,
    is_default INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1)),
    PRIMARY KEY (node_id, preset_id)
) STRICT;
CREATE TABLE node_dns_run (
    node_id TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    at_unix INTEGER NOT NULL,
    p50_ms  INTEGER NOT NULL,
    p95_ms  INTEGER NOT NULL,
    failed  INTEGER NOT NULL,
    domains INTEGER NOT NULL,
    PRIMARY KEY (node_id, at_unix)
) WITHOUT ROWID;
CREATE TABLE node_facts (
    node_id             TEXT PRIMARY KEY REFERENCES node (id) ON DELETE CASCADE,
    hostname            TEXT    NOT NULL DEFAULT '',
    os                  TEXT    NOT NULL DEFAULT '',
    kernel              TEXT    NOT NULL DEFAULT '',
    arch                TEXT    NOT NULL DEFAULT '',
    cpu_count           INTEGER NOT NULL DEFAULT 0,
    ram_total_bytes     INTEGER NOT NULL DEFAULT 0,
    disk_total_bytes    INTEGER NOT NULL DEFAULT 0,
    virt                TEXT    NOT NULL DEFAULT '',
    has_ipv6            INTEGER NOT NULL DEFAULT 0 CHECK (has_ipv6 IN (0, 1)),
    engines_json        TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(engines_json)),  -- [{protocol, version}]
    extra_json          TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(extra_json)),
    updated_at          INTEGER NOT NULL
) STRICT;
CREATE TABLE node_host_hour (
    node_id          TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    hour_start       INTEGER NOT NULL CHECK (hour_start % 3600 = 0),
    samples          INTEGER NOT NULL DEFAULT 0,
    cpu_sum_x100     INTEGER NOT NULL DEFAULT 0,
    cpu_max_x100     INTEGER NOT NULL DEFAULT 0,
    softirq_max_x100 INTEGER NOT NULL DEFAULT 0,
    load1_max_x100   INTEGER NOT NULL DEFAULT 0,
    ram_used_max     INTEGER NOT NULL DEFAULT 0,
    ram_total        INTEGER NOT NULL DEFAULT 0,
    rx_bps_sum       INTEGER NOT NULL DEFAULT 0,
    rx_bps_max       INTEGER NOT NULL DEFAULT 0,
    tx_bps_sum       INTEGER NOT NULL DEFAULT 0,
    tx_bps_max       INTEGER NOT NULL DEFAULT 0,
    sessions_max     INTEGER NOT NULL DEFAULT 0, ext_samples        INTEGER NOT NULL DEFAULT 0, sessions_sum       INTEGER NOT NULL DEFAULT 0, steal_sum_x100     INTEGER NOT NULL DEFAULT 0, steal_max_x100     INTEGER NOT NULL DEFAULT 0, iowait_max_x100    INTEGER NOT NULL DEFAULT 0, swap_used_max      INTEGER NOT NULL DEFAULT 0, conntrack_max      INTEGER NOT NULL DEFAULT 0, conntrack_limit    INTEGER NOT NULL DEFAULT 0, tcp_sockets_max    INTEGER NOT NULL DEFAULT 0, nic_speed_mbps     INTEGER NOT NULL DEFAULT 0, agent_cpu_sum_x100 INTEGER NOT NULL DEFAULT 0, agent_cpu_max_x100 INTEGER NOT NULL DEFAULT 0, agent_rss_max      INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (node_id, hour_start)
) STRICT, WITHOUT ROWID;
CREATE TABLE node_inbound_stats_tombstone (
    node_id    TEXT NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    inbound_id TEXT NOT NULL,
    protocol   TEXT NOT NULL,
    PRIMARY KEY (node_id, inbound_id)
) STRICT, WITHOUT ROWID;
CREATE TABLE node_journal (
    node_id    TEXT    NOT NULL,
    hour_start INTEGER NOT NULL,
    key        TEXT    NOT NULL,
    level      INTEGER NOT NULL CHECK (level IN (2, 3)),
    source     TEXT    NOT NULL,
    message    TEXT    NOT NULL,
    inbound_id TEXT    NOT NULL DEFAULT '',
    attrs_json TEXT    NOT NULL DEFAULT '{}',
    count      INTEGER NOT NULL,
    first_at   INTEGER NOT NULL,
    last_at    INTEGER NOT NULL,
    PRIMARY KEY (node_id, hour_start, key)
) STRICT;
CREATE TABLE node_live (
    node_id   TEXT PRIMARY KEY REFERENCES node(id) ON DELETE CASCADE,
    session   INTEGER NOT NULL,
    drift     INTEGER NOT NULL DEFAULT 0,
    sample_at INTEGER NOT NULL DEFAULT 0,
    rx_bps    INTEGER NOT NULL DEFAULT 0,
    tx_bps    INTEGER NOT NULL DEFAULT 0,
    cpu_pct   INTEGER NOT NULL DEFAULT 0,
    users     TEXT    NOT NULL DEFAULT '{}',
    live_json TEXT    NOT NULL DEFAULT '{}'
, devices TEXT NOT NULL DEFAULT '{}');
CREATE TABLE node_os_status (
    node_id TEXT PRIMARY KEY NOT NULL REFERENCES node(id) ON DELETE CASCADE,
    status_json TEXT NOT NULL CHECK (json_valid(status_json)),
    measured_at INTEGER NOT NULL,
    received_at INTEGER NOT NULL
) STRICT;
CREATE TABLE node_port_check (
    node_id    TEXT    NOT NULL REFERENCES node(id) ON DELETE CASCADE,
    port       INTEGER NOT NULL,
    address    TEXT    NOT NULL,
    sent       INTEGER NOT NULL,
    got        INTEGER NOT NULL,
    verdict    TEXT    NOT NULL,
    sender     TEXT    NOT NULL,
    checked_at INTEGER NOT NULL,
    bad_at     INTEGER NOT NULL DEFAULT 0, sender_verdict TEXT NOT NULL DEFAULT '', confirm_sender TEXT NOT NULL DEFAULT '', confirm_sent INTEGER NOT NULL DEFAULT 0, confirm_got INTEGER NOT NULL DEFAULT 0, confirm_verdict TEXT NOT NULL DEFAULT '', blame TEXT NOT NULL DEFAULT '' CHECK (blame IN ('', 'node', 'path')),
    PRIMARY KEY (node_id, port)
);
CREATE TABLE node_provision_event (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    job_id      TEXT    NOT NULL REFERENCES node_provision_job (id) ON DELETE CASCADE,
    phase       TEXT    NOT NULL,
    code        TEXT    NOT NULL,
    created_at  INTEGER NOT NULL
) STRICT;
CREATE TABLE "node_provision_job" (
    id                  TEXT    PRIMARY KEY,
    node_id             TEXT    NOT NULL UNIQUE,
    name                TEXT    NOT NULL,
    address             TEXT    NOT NULL,
    country_code        TEXT    NOT NULL DEFAULT '',
    location            TEXT    NOT NULL DEFAULT '',
    provider            TEXT    NOT NULL DEFAULT '',
    ssh_host            TEXT    NOT NULL,
    ssh_port            INTEGER NOT NULL CHECK (ssh_port BETWEEN 1 AND 65535),
    host_fingerprint    TEXT    NOT NULL,
    secret              BLOB    NOT NULL,
    state               TEXT    NOT NULL CHECK (state IN ('queued', 'running', 'cancel_requested', 'cancelled', 'completed', 'failed')),
    phase               TEXT    NOT NULL,
    error_code          TEXT    NOT NULL DEFAULT '',
    created_by          TEXT    NOT NULL,
    created_at          INTEGER NOT NULL,
    updated_at          INTEGER NOT NULL
, attempt INTEGER NOT NULL DEFAULT 0, sharing TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE node_sent (
    node_id TEXT PRIMARY KEY REFERENCES node(id) ON DELETE CASCADE,
    digest TEXT NOT NULL
);
CREATE TABLE node_server_access (
    node_id             TEXT    PRIMARY KEY REFERENCES node (id) ON DELETE CASCADE,
    node_name           TEXT    NOT NULL,
    ssh_host            TEXT    NOT NULL,
    ssh_port            INTEGER NOT NULL CHECK (ssh_port BETWEEN 1 AND 65535),
    ssh_username        TEXT    NOT NULL,
    host_fingerprint    TEXT    NOT NULL,
    password            BLOB    NOT NULL,
    pending_password    BLOB,
    configured_at       INTEGER NOT NULL
, password_generated INTEGER NOT NULL DEFAULT 0, panel_key_fp TEXT NOT NULL DEFAULT '', password_login INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE TABLE node_shared_ports (
    node_id    TEXT PRIMARY KEY REFERENCES node(id) ON DELETE CASCADE,
    at_unix    INTEGER NOT NULL,
    ports_json TEXT    NOT NULL
);
CREATE TABLE node_sni_scan (
    node_id     TEXT    PRIMARY KEY REFERENCES node (id) ON DELETE CASCADE,
    at_unix     INTEGER NOT NULL,
    result_json TEXT    NOT NULL
);
CREATE TABLE node_speed_test (
    node_id TEXT NOT NULL REFERENCES node(id) ON DELETE CASCADE,
    at      INTEGER NOT NULL,
    PRIMARY KEY (node_id, at)
);
CREATE TABLE node_tcp_check (
    node_id    TEXT    NOT NULL REFERENCES node(id) ON DELETE CASCADE,
    port       INTEGER NOT NULL,
    role       TEXT    NOT NULL,
    alpn       INTEGER NOT NULL DEFAULT 0,
    profile    TEXT    NOT NULL DEFAULT '',
    verdict    TEXT    NOT NULL,
    reason     TEXT    NOT NULL DEFAULT '',
    sender     TEXT    NOT NULL,
    checked_at INTEGER NOT NULL,
    PRIMARY KEY (node_id, port)
);
CREATE TABLE node_trace (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    from_node_id TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    to_node_id   TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    at_unix      INTEGER NOT NULL,
    result_json  TEXT    NOT NULL
);
CREATE TABLE node_traffic_hour (
    node_id             TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    protocol            TEXT    NOT NULL,
    hour_start          INTEGER NOT NULL CHECK (hour_start % 3600 = 0),
    bytes_up            INTEGER NOT NULL DEFAULT 0,
    bytes_down          INTEGER NOT NULL DEFAULT 0,
    peak_users          INTEGER NOT NULL DEFAULT 0,             -- max distinct users online in any snapshot of the hour
    peak_devices        INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (node_id, protocol, hour_start)
) STRICT, WITHOUT ROWID;
CREATE TABLE node_update_schedule (
    node_id                    TEXT PRIMARY KEY REFERENCES node (id) ON DELETE CASCADE,
    to_version                 TEXT    NOT NULL,
    to_built                   INTEGER NOT NULL,
    scheduled_at               INTEGER NOT NULL,
    timezone_offset_minutes    INTEGER NOT NULL CHECK (timezone_offset_minutes BETWEEN -720 AND 840),
    created_by                 TEXT    NOT NULL DEFAULT '',
    created_at                 INTEGER NOT NULL
, missed_at INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE os_rollout (
    id                TEXT PRIMARY KEY,                                   -- osr_...
    status            TEXT    NOT NULL CHECK (status IN ('running', 'paused', 'done', 'cancelled', 'failed')),
    mode              TEXT    NOT NULL CHECK (mode IN ('security', 'all', 'reboot_only')),
    reboot            TEXT    NOT NULL CHECK (reboot IN ('never', 'if_required', 'always')),
    batch_size        INTEGER NOT NULL DEFAULT 1 CHECK (batch_size BETWEEN 1 AND 5),
    window_start      INTEGER NOT NULL DEFAULT -1,                        -- minute of the day, -1 = no window
    window_end        INTEGER NOT NULL DEFAULT -1,
    tz_offset         INTEGER NOT NULL DEFAULT 0,                         -- the update time zone when it was created
    max_online        INTEGER NOT NULL DEFAULT 0,                         -- 0 = ignore
    pause_key         TEXT    NOT NULL DEFAULT '',
    pause_params_json TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(pause_params_json)),
    created_by        TEXT    NOT NULL DEFAULT '',
    created_at        INTEGER NOT NULL,
    finished_at       INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE os_step (
    rollout_id      TEXT    NOT NULL REFERENCES os_rollout (id) ON DELETE CASCADE,
    node_id         TEXT    NOT NULL,
    node_name       TEXT    NOT NULL,
    stage           INTEGER NOT NULL,
    state           TEXT    NOT NULL CHECK (state IN ('pending', 'sent', 'rebooting', 'gating', 'passed', 'failed', 'skipped')),
    job_id          TEXT    NOT NULL DEFAULT '',                          -- osj_...; a new attempt is a new id
    sends           INTEGER NOT NULL DEFAULT 0,                           -- times UpdateOs was sent under job_id (a lost answer is sent again)
    acked_at        INTEGER NOT NULL DEFAULT 0,                           -- the node answered started / running with this job id
    phase           TEXT    NOT NULL DEFAULT '',
    phase_at        INTEGER NOT NULL DEFAULT 0,
    boot_before     INTEGER NOT NULL DEFAULT 0,                           -- the node's boot time when the job was sent
    kernel_from     TEXT    NOT NULL DEFAULT '',
    kernel_to       TEXT    NOT NULL DEFAULT '',
    pre_failed_json TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(pre_failed_json)),  -- inbounds FAILED before the job
    sent_at         INTEGER NOT NULL DEFAULT 0,
    reboot_at       INTEGER NOT NULL DEFAULT 0,
    back_at         INTEGER NOT NULL DEFAULT 0,                           -- the check window opened (back after the reboot, or the job ended)
    finished_at     INTEGER NOT NULL DEFAULT 0,
    error_key       TEXT    NOT NULL DEFAULT '',
    params_json     TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(params_json)),
    PRIMARY KEY (rollout_id, node_id)
) STRICT;
CREATE TABLE own_probe (
    id                TEXT PRIMARY KEY CHECK (id GLOB 'prb_*'),
    name              TEXT NOT NULL,
    city              TEXT NOT NULL,
    kind              TEXT NOT NULL CHECK (kind IN ('home', 'mobile', 'dc')),
    token_hash        BLOB,
    token_expires     INTEGER NOT NULL DEFAULT 0,
    secret_hash       BLOB,
    state             TEXT NOT NULL CHECK (state IN ('pending', 'active', 'network_changed', 'revoked')),
    asn               INTEGER NOT NULL DEFAULT 0,
    operator          TEXT NOT NULL DEFAULT '',
    pinned_operator   TEXT NOT NULL DEFAULT '',
    version           TEXT NOT NULL DEFAULT '',
    last_seen         INTEGER NOT NULL DEFAULT 0,
    last_result       INTEGER NOT NULL DEFAULT 0,
    checks_day        INTEGER NOT NULL DEFAULT 0 CHECK (checks_day >= 0),
    checks_day_at     INTEGER NOT NULL DEFAULT 0,
    job_id            TEXT NOT NULL DEFAULT '',
    job_json          TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(job_json)),
    job_due           INTEGER NOT NULL DEFAULT 0,
    created_at        INTEGER NOT NULL,
    created_by        TEXT NOT NULL,
    CHECK (token_hash IS NULL OR (typeof(token_hash) = 'blob' AND length(token_hash) = 32)),
    CHECK (secret_hash IS NULL OR (typeof(secret_hash) = 'blob' AND length(secret_hash) = 32))
) STRICT;
CREATE TABLE panel_backup_settings (
    id                  INTEGER PRIMARY KEY CHECK (id = 1),
    account_id          TEXT    NOT NULL DEFAULT '',
    jurisdiction        TEXT    NOT NULL DEFAULT 'default',
    bucket              TEXT    NOT NULL DEFAULT '',
    access_key_id       TEXT    NOT NULL DEFAULT '',
    secret_access_key   BLOB    NOT NULL DEFAULT X'',
    age_recipient       TEXT    NOT NULL DEFAULT '',
    enabled             INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
    interval_hours      INTEGER NOT NULL DEFAULT 24 CHECK (interval_hours BETWEEN 1 AND 168),
    retention_days      INTEGER NOT NULL DEFAULT 0 CHECK (retention_days = 0 OR retention_days BETWEEN 7 AND 3650),
    last_success        INTEGER NOT NULL DEFAULT 0,
    last_error_code     TEXT    NOT NULL DEFAULT '',
    updated_at          INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE panel_ca (
    id                  TEXT PRIMARY KEY,                       -- cas_...
    cert_pem            TEXT    NOT NULL,
    fingerprint_sha256  TEXT    NOT NULL,                       -- hex of the DER certificate; what install commands carry
    key_enc             BLOB    NOT NULL,                       -- vault, AAD = id (PKCS#8 ECDSA P-256)
    not_before          INTEGER NOT NULL,
    not_after           INTEGER NOT NULL,
    active              INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
    created_at          INTEGER NOT NULL
) STRICT;
CREATE TABLE panel_ssh_key (
    id          INTEGER PRIMARY KEY CHECK (id = 1),
    private_key BLOB    NOT NULL,
    public_key  TEXT    NOT NULL,
    fingerprint TEXT    NOT NULL,
    created_at  INTEGER NOT NULL
) STRICT;
CREATE TABLE passkey (
    id               TEXT PRIMARY KEY,
    admin_id         TEXT NOT NULL REFERENCES admin(id) ON DELETE CASCADE,
    credential_id    BLOB NOT NULL UNIQUE,
    public_key       BLOB NOT NULL,          -- COSE key
    attestation_type TEXT NOT NULL DEFAULT '',
    sign_count       INTEGER NOT NULL DEFAULT 0,
    aaguid           BLOB NOT NULL DEFAULT x'',
    transports       TEXT NOT NULL DEFAULT '',   -- comma separated
    flags            INTEGER NOT NULL DEFAULT 0, -- raw authenticator data flags byte (UP/UV/BE/BS)
    name             TEXT NOT NULL DEFAULT '',
    created_at       INTEGER NOT NULL,
    last_used_at     INTEGER
) STRICT;
CREATE TABLE path_probe (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    from_node_id TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    to_node_id   TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    kind         TEXT    NOT NULL CHECK (kind IN ('udp', 'tcp', 'tls')),
    at_unix      INTEGER NOT NULL,
    result_json  TEXT    NOT NULL
);
CREATE TABLE path_speed (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    from_node_id TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    to_node_id   TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    direction    TEXT    NOT NULL CHECK (direction IN ('down', 'up')),
    at_unix      INTEGER NOT NULL,
    result_json  TEXT    NOT NULL
);
CREATE TABLE path_speed_start (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    actor_id     TEXT    NOT NULL,
    from_node_id TEXT    NOT NULL,
    to_node_id   TEXT    NOT NULL,
    at_unix      INTEGER NOT NULL
);
CREATE TABLE profile (
    id                  TEXT PRIMARY KEY,                       -- prf_...
    protocol            TEXT    NOT NULL,                       -- plugin id: "hysteria2"
    name                TEXT    NOT NULL COLLATE NOCASE UNIQUE,
    settings_json       TEXT    NOT NULL CHECK (json_valid(settings_json)),  -- validated by the plugin; NO secrets inside
    secrets_enc         BLOB,                                   -- vault, AAD = id; JSON object {json-pointer: value} of x-secret fields
    version             INTEGER NOT NULL DEFAULT 1,             -- bumped on every change; optimistic concurrency
    created_at          INTEGER NOT NULL,
    updated_at          INTEGER NOT NULL
, critical_epoch INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE recovery_token (
    hash       BLOB PRIMARY KEY,
    expires_at INTEGER NOT NULL,
    used_at    INTEGER
) STRICT, WITHOUT ROWID;
CREATE TABLE relay (
    id          TEXT    PRIMARY KEY,
    inbound_id  TEXT    NOT NULL REFERENCES inbound (id) ON DELETE CASCADE,
    via_node_id TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    network     TEXT    NOT NULL CHECK (network IN ('tcp', 'udp')),
    port        INTEGER NOT NULL CHECK (port = 443 OR port BETWEEN 1024 AND 65535),
    enabled     INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
    state       TEXT    NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'active', 'failed')),
    last_error  TEXT    NOT NULL DEFAULT '',
    to_ip       TEXT    NOT NULL DEFAULT '',
    applied_at  INTEGER NOT NULL DEFAULT 0,
    check_json  TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(check_json)),
    created_at  INTEGER NOT NULL,
    updated_at  INTEGER NOT NULL, mode TEXT NOT NULL DEFAULT 'auto' CHECK (mode IN ('auto', 'dnat', 'reverse')), active_mode TEXT NOT NULL DEFAULT 'dnat' CHECK (active_mode IN ('dnat', 'reverse')), mode_changed_at INTEGER NOT NULL DEFAULT 0, mode_reason TEXT NOT NULL DEFAULT '', leg TEXT NOT NULL DEFAULT 'auto' CHECK (leg IN ('auto', 'ipv4', 'ipv6')), active_leg TEXT NOT NULL DEFAULT '4' CHECK (active_leg IN ('4', '6')), leg_tried_at INTEGER NOT NULL DEFAULT 0,
    UNIQUE (inbound_id, via_node_id),
    UNIQUE (via_node_id, network, port)
) STRICT;
CREATE TABLE scheduled_task (
    id              TEXT    PRIMARY KEY,
    name            TEXT    NOT NULL,
    kind            TEXT    NOT NULL CHECK (kind IN ('check', 'assistant')),
    enabled         INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    schedule_kind   TEXT    NOT NULL CHECK (schedule_kind IN ('every', 'daily', 'weekly')),
    every_minutes   INTEGER NOT NULL DEFAULT 0,
    minute_of_day   INTEGER NOT NULL DEFAULT 0,
    weekday         INTEGER NOT NULL DEFAULT 0,
    steps           TEXT    NOT NULL DEFAULT '[]',
    prompt_enc      BLOB    NOT NULL DEFAULT X'',
    notify_telegram INTEGER NOT NULL DEFAULT 0 CHECK (notify_telegram IN (0, 1)),
    conversation_id TEXT    NOT NULL DEFAULT '',
    jitter_s        INTEGER NOT NULL DEFAULT 0,
    created_by      TEXT    NOT NULL,
    created_at      INTEGER NOT NULL,
    updated_at      INTEGER NOT NULL,
    next_run_at     INTEGER NOT NULL DEFAULT 0,
    lease_id        TEXT    NOT NULL DEFAULT '',
    lease_until     INTEGER NOT NULL DEFAULT 0,
    last_manual_at  INTEGER NOT NULL DEFAULT 0,
    fail_streak     INTEGER NOT NULL DEFAULT 0,
    fail_reason     TEXT    NOT NULL DEFAULT '',
    problem         INTEGER NOT NULL DEFAULT 0 CHECK (problem IN (0, 1)),
    problem_summary TEXT    NOT NULL DEFAULT ''
, version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0)) STRICT;
CREATE TABLE scheduled_task_run (
    id          TEXT    PRIMARY KEY,
    task_id     TEXT    NOT NULL,
    trigger_kind TEXT   NOT NULL CHECK (trigger_kind IN ('schedule', 'manual', 'missed')),
    status      TEXT    NOT NULL CHECK (status IN ('running', 'ok', 'problem', 'failed', 'skipped')),
    reason      TEXT    NOT NULL DEFAULT '',
    summary     TEXT    NOT NULL DEFAULT '',
    detail      TEXT    NOT NULL DEFAULT '{}',
    actor       TEXT    NOT NULL DEFAULT '',
    started_at  INTEGER NOT NULL,
    finished_at INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE session (
    token_hash   BLOB PRIMARY KEY,           -- SHA-256 of the cookie value
    admin_id     TEXT NOT NULL REFERENCES admin(id) ON DELETE CASCADE,
    created_at   INTEGER NOT NULL,
    last_seen_at INTEGER NOT NULL,
    expires_at   INTEGER NOT NULL,           -- absolute lifetime
    ip           TEXT NOT NULL DEFAULT '',
    user_agent   TEXT NOT NULL DEFAULT ''
, stepup_at INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE setting (
    k TEXT PRIMARY KEY,
    v TEXT NOT NULL
) STRICT;
CREATE TABLE setup_token (
    hash       BLOB PRIMARY KEY,             -- SHA-256 of the one-time token
    expires_at INTEGER NOT NULL,
    used_at    INTEGER
) STRICT;
CREATE TABLE telegram_bot (
    id          INTEGER PRIMARY KEY CHECK (id = 1),
    token       BLOB NOT NULL,          -- vault ciphertext, record "telegram_bot.token"; never returned by an RPC
    bot_id      INTEGER NOT NULL,       -- from getMe: tells a new bot from the same one pasted again
    username    TEXT NOT NULL,
    updated_at  INTEGER NOT NULL
) STRICT;
CREATE TABLE telegram_link (
    admin_id   TEXT PRIMARY KEY REFERENCES admin(id) ON DELETE CASCADE,
    chat_id    INTEGER NOT NULL UNIQUE,
    enabled    INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    linked_at  INTEGER NOT NULL
) STRICT;
CREATE TABLE telegram_link_code (
    hash       TEXT PRIMARY KEY CHECK (length(hash) = 64),
    admin_id   TEXT NOT NULL UNIQUE REFERENCES admin(id) ON DELETE CASCADE,
    expires_at INTEGER NOT NULL
) STRICT;
CREATE TABLE traffic_bucket (
    user_id             TEXT    NOT NULL REFERENCES user (id) ON DELETE CASCADE,
    node_id             TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    protocol            TEXT    NOT NULL,
    hour_start          INTEGER NOT NULL CHECK (hour_start % 3600 = 0),
    bytes_up            INTEGER NOT NULL DEFAULT 0,             -- client -> internet
    bytes_down          INTEGER NOT NULL DEFAULT 0,             -- internet -> client
    PRIMARY KEY (user_id, node_id, protocol, hour_start)
) STRICT, WITHOUT ROWID;
CREATE TABLE udp_path_loss (
    sender_id       TEXT    NOT NULL REFERENCES node(id) ON DELETE CASCADE,
    target_id       TEXT    NOT NULL REFERENCES node(id) ON DELETE CASCADE,
    ports           TEXT    NOT NULL,
    sent            INTEGER NOT NULL,
    got             INTEGER NOT NULL,
    other_sender_id TEXT    NOT NULL REFERENCES node(id) ON DELETE CASCADE,
    other_got       INTEGER NOT NULL,
    checked_at      INTEGER NOT NULL, open_ports TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (sender_id, target_id)
);
CREATE TABLE update_rollout (
    id                TEXT PRIMARY KEY,                                   -- rol_...
    status            TEXT    NOT NULL CHECK (status IN ('running', 'paused', 'done', 'cancelled', 'failed')),
    to_version        TEXT    NOT NULL,
    to_built          INTEGER NOT NULL,
    manifest          BLOB    NOT NULL,                                   -- the signed bytes
    signature         BLOB    NOT NULL,
    batch_size        INTEGER NOT NULL CHECK (batch_size BETWEEN 1 AND 10),
    pause_key         TEXT    NOT NULL DEFAULT '',
    pause_params_json TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(pause_params_json)),
    created_by        TEXT    NOT NULL DEFAULT '',                        -- admin id
    created_at        INTEGER NOT NULL,
    finished_at       INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE update_step (
    rollout_id        TEXT    NOT NULL REFERENCES update_rollout (id) ON DELETE CASCADE,
    node_id           TEXT    NOT NULL,                                   -- no FK: a retired node keeps its history
    node_name         TEXT    NOT NULL,
    stage             INTEGER NOT NULL,                                   -- 0 = canary
    state             TEXT    NOT NULL CHECK (state IN ('pending', 'sent', 'gating', 'passed', 'failed', 'rolled_back', 'skipped')),
    from_version      TEXT    NOT NULL DEFAULT '',
    from_built        INTEGER NOT NULL DEFAULT 0,
    pre_failed_json   TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(pre_failed_json)),  -- inbounds FAILED before the update
    sent_at           INTEGER NOT NULL DEFAULT 0,
    acked_at          INTEGER NOT NULL DEFAULT 0,                         -- the agent answered UpdateAgent with ok
    reconnected_at    INTEGER NOT NULL DEFAULT 0,
    finished_at       INTEGER NOT NULL DEFAULT 0,
    error_key         TEXT    NOT NULL DEFAULT '',
    params_json       TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(params_json)), request_id TEXT NOT NULL DEFAULT '', request_at INTEGER NOT NULL DEFAULT 0, answer_json TEXT NOT NULL DEFAULT '', download_sha TEXT NOT NULL DEFAULT '', progress_phase TEXT NOT NULL DEFAULT '', progress_rank INTEGER NOT NULL DEFAULT -1, progress_downloaded INTEGER NOT NULL DEFAULT 0, progress_total INTEGER NOT NULL DEFAULT 0, progress_speed INTEGER NOT NULL DEFAULT 0, progress_updated_unix INTEGER NOT NULL DEFAULT 0, progress_error TEXT NOT NULL DEFAULT '', answer_wait_seconds INTEGER NOT NULL DEFAULT 0, progress_source TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (rollout_id, node_id)
) STRICT;
CREATE TABLE user (
    id                  TEXT PRIMARY KEY,                       -- usr_...
    name                TEXT    NOT NULL COLLATE NOCASE UNIQUE,
    group_id            TEXT    NOT NULL REFERENCES user_group (id) ON DELETE RESTRICT,
    disabled            INTEGER NOT NULL DEFAULT 0 CHECK (disabled IN (0, 1)),   -- admin switch
    -- Derived, maintained by the access module (on usage ingest, on edits, and by a minute timer for
    -- expiry). Precedence: disabled > expired > limited > active. Stored so that filters are index scans.
    status              TEXT    NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled', 'expired', 'limited')),
    app_happ            INTEGER NOT NULL DEFAULT 1 CHECK (app_happ    IN (0, 1)),
    app_amnezia         INTEGER NOT NULL DEFAULT 1 CHECK (app_amnezia IN (0, 1)),
    all_nodes           INTEGER NOT NULL DEFAULT 1 CHECK (all_nodes IN (0, 1)),  -- 1 = automatic incl. future nodes; 0 = see user_node
    quota_bytes         INTEGER NOT NULL DEFAULT 0 CHECK (quota_bytes >= 0),     -- 0 = unlimited
    quota_reset         TEXT    NOT NULL DEFAULT 'month' CHECK (quota_reset IN ('none', 'day', 'week', 'month', 'rolling_month')),
    period_start        INTEGER NOT NULL,                       -- start of the current quota period
    used_bytes          INTEGER NOT NULL DEFAULT 0,             -- up+down in the current period; incremented in the stats transaction
    expires_at          INTEGER,                                -- NULL = never
    device_limit        INTEGER NOT NULL DEFAULT 5 CHECK (device_limit BETWEEN 1 AND 100),
    speed_limit_bps     INTEGER NOT NULL DEFAULT 0 CHECK (speed_limit_bps >= 0), -- 0 = none (experimental)
    -- Subscription token: lookup by hash, re-display by decrypting. Rotation replaces both.
    sub_token_hash      BLOB    NOT NULL UNIQUE,                -- sha256(token)
    sub_token_enc       BLOB    NOT NULL,                       -- vault, AAD = id
    last_seen_at        INTEGER NOT NULL DEFAULT 0,
    last_node_id        TEXT    REFERENCES node (id) ON DELETE SET NULL,
    created_at          INTEGER NOT NULL, dns_preset_id TEXT, subscription_name TEXT NOT NULL DEFAULT '', device_speed_limit_bps INTEGER NOT NULL DEFAULT 0 CHECK (device_speed_limit_bps >= 0), app_telegram INTEGER NOT NULL DEFAULT 0
    CHECK (app_telegram IN (0, 1)), app_mistgate_off INTEGER NOT NULL DEFAULT 0
    CHECK (app_mistgate_off IN (0, 1)), app_trusttunnel INTEGER NOT NULL DEFAULT 0
    CHECK (app_trusttunnel IN (0, 1)), page_pass_gen INTEGER NOT NULL DEFAULT 0
    CHECK (page_pass_gen >= 0), page_open INTEGER NOT NULL DEFAULT 0
    CHECK (page_open IN (0, 1)),
    CHECK (app_happ = 1 OR app_amnezia = 1)                     -- "at least one app"
) STRICT;
CREATE TABLE user_extra_group (
    user_id  TEXT NOT NULL REFERENCES user (id)       ON DELETE CASCADE,
    group_id TEXT NOT NULL REFERENCES user_group (id) ON DELETE CASCADE,
    PRIMARY KEY (user_id, group_id)
) STRICT, WITHOUT ROWID;
CREATE TABLE user_group (
    id                  TEXT PRIMARY KEY,                       -- grp_...
    name                TEXT    NOT NULL COLLATE NOCASE UNIQUE,
    created_at          INTEGER NOT NULL
, dns_preset_id TEXT, color TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE user_group_disabled_node (
    group_id TEXT NOT NULL REFERENCES user_group (id) ON DELETE CASCADE,
    node_id  TEXT NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    PRIMARY KEY (group_id, node_id)
) STRICT, WITHOUT ROWID;
CREATE TABLE user_group_profile (
    group_id            TEXT NOT NULL REFERENCES user_group (id) ON DELETE CASCADE,
    profile_id          TEXT NOT NULL REFERENCES profile (id)    ON DELETE CASCADE,
    PRIMARY KEY (group_id, profile_id)
) STRICT, WITHOUT ROWID;
CREATE TABLE user_link_dns (
    user_id    TEXT    NOT NULL PRIMARY KEY REFERENCES user (id) ON DELETE CASCADE,
    preset_id  TEXT    NOT NULL REFERENCES dns_preset (id) ON DELETE CASCADE,
    updated_at INTEGER NOT NULL
) STRICT;
CREATE TABLE user_network (
    user_id   TEXT    NOT NULL,
    asn       INTEGER NOT NULL,
    connects  INTEGER NOT NULL,
    last_hour INTEGER NOT NULL,
    PRIMARY KEY (user_id, asn)
) STRICT;
CREATE TABLE user_node (
    user_id             TEXT NOT NULL REFERENCES user (id) ON DELETE CASCADE,
    node_id             TEXT NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    PRIMARY KEY (user_id, node_id)
) STRICT, WITHOUT ROWID;
CREATE TABLE user_node_dns (
    user_id    TEXT    NOT NULL REFERENCES user (id) ON DELETE CASCADE,
    node_id    TEXT    NOT NULL REFERENCES node (id) ON DELETE CASCADE,
    preset_id  TEXT    NOT NULL REFERENCES dns_preset (id) ON DELETE CASCADE,
    updated_at INTEGER NOT NULL,
    PRIMARY KEY (user_id, node_id)
) STRICT;
CREATE TABLE warp_account (                        -- at most one per node
    node_id           TEXT PRIMARY KEY REFERENCES node (id) ON DELETE CASCADE,
    source            TEXT    NOT NULL CHECK (source IN ('registered', 'imported')),
    -- vault, AAD = node_id: {"private_key","token","reg_id","license"}; token, reg_id and license are empty for an
    -- imported profile that came without wgcf-account.toml.
    secret_enc        BLOB    NOT NULL,
    peer_public_key   TEXT    NOT NULL,            -- always from the account, never a constant
    endpoint_v4       TEXT    NOT NULL,            -- IP literal, ":0" stripped
    endpoint_v6       TEXT    NOT NULL DEFAULT '',
    ports_json        TEXT    NOT NULL DEFAULT '[2408,500,1701,4500]' CHECK (json_valid(ports_json)),
    address_v4        TEXT    NOT NULL,            -- "172.16.0.2/32"
    address_v6        TEXT    NOT NULL DEFAULT '', -- new accounts may have none
    mtu               INTEGER NOT NULL DEFAULT 1280,
    client_id         TEXT    NOT NULL DEFAULT '', -- base64; its first 3 bytes are the "reserved" bytes
    use_reserved      INTEGER NOT NULL DEFAULT 0 CHECK (use_reserved IN (0, 1)),
    account_type      TEXT    NOT NULL DEFAULT '', -- free | plus, informational
    enabled           INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    tos_url           TEXT    NOT NULL DEFAULT '', -- what the owner was shown
    tos_accepted_by   TEXT    NOT NULL DEFAULT '', -- admin id; '' for an import
    tos_accepted_at   INTEGER NOT NULL DEFAULT 0,
    registered_with   TEXT    NOT NULL DEFAULT '', -- API version + user agent at registration (429 diagnosis)
    attention         TEXT    NOT NULL DEFAULT '', -- reason code when the owner has to decide (registration failed, revoked); '' = fine
    health_json       TEXT    NOT NULL DEFAULT '' CHECK (health_json = '' OR json_valid(health_json)),  -- last agent.v1.WarpHealth
    health_at         INTEGER NOT NULL DEFAULT 0,  -- when it was reported; 0 = never
    created_at        INTEGER NOT NULL,
    updated_at        INTEGER NOT NULL
, reach_json TEXT NOT NULL DEFAULT '', reach_at INTEGER NOT NULL DEFAULT 0) STRICT;
